import json
import socket
import time

TARGET = "192.168.1.3"
TIMEOUT_SECONDS = 3.0


def ber_length(length):
    if length < 128:
        return bytes([length])
    encoded = length.to_bytes((length.bit_length() + 7) // 8, "big")
    return bytes([0x80 | len(encoded)]) + encoded


def tlv(tag, value):
    return bytes([tag]) + ber_length(len(value)) + value


def ber_integer(value):
    if value == 0:
        raw = b"\x00"
    else:
        size = max(1, (value.bit_length() + 7) // 8)
        raw = value.to_bytes(size, "big")
        if raw[0] & 0x80:
            raw = b"\x00" + raw
    return tlv(0x02, raw)


def oid_bytes(parts):
    values = [40 * parts[0] + parts[1]] + parts[2:]
    encoded = bytearray()
    for value in values:
        groups = [value & 0x7f]
        value >>= 7
        while value:
            groups.append(0x80 | (value & 0x7f))
            value >>= 7
        encoded.extend(reversed(groups))
    return bytes(encoded)


def snmpv3_discovery_request():
    request_id = int(time.time()) & 0x7fffffff
    varbind = tlv(0x30, tlv(0x06, oid_bytes([1, 3, 6, 1, 2, 1, 1, 1, 0])) + tlv(0x05, b""))
    varbind_list = tlv(0x30, varbind)
    get_request = tlv(0xa0, ber_integer(request_id) + ber_integer(0) + ber_integer(0) + varbind_list)
    scoped_pdu = tlv(0x30, tlv(0x04, b"") + tlv(0x04, b"") + get_request)
    global_data = tlv(0x30, ber_integer(request_id) + ber_integer(65507) + tlv(0x04, b"\x04") + ber_integer(3))
    usm_parameters = tlv(0x30, tlv(0x04, b"") + ber_integer(0) + ber_integer(0) + tlv(0x04, b"") + tlv(0x04, b"") + tlv(0x04, b""))
    return tlv(0x30, ber_integer(3) + global_data + tlv(0x04, usm_parameters) + tlv(0x04, scoped_pdu))


def read_tlv(data, offset):
    if offset + 2 > len(data):
        raise ValueError("truncated BER tag or length")
    tag = data[offset]
    first = data[offset + 1]
    offset += 2
    if first < 0x80:
        length = first
    else:
        count = first & 0x7f
        if count == 0 or count > 4 or offset + count > len(data):
            raise ValueError("invalid or incomplete BER length")
        length = int.from_bytes(data[offset:offset + count], "big")
        offset += count
    end = offset + length
    if end > len(data):
        raise ValueError("BER value extends beyond response")
    return tag, data[offset:end], end


def parse_snmpv3_response(data):
    tag, body, end = read_tlv(data, 0)
    if tag != 0x30 or end != len(data):
        raise ValueError("response is not one complete BER sequence")
    tag, version, offset = read_tlv(body, 0)
    if tag != 0x02 or not version:
        raise ValueError("missing SNMP version integer")
    version_number = int.from_bytes(version, "big", signed=True)
    if version_number != 3:
        raise ValueError("BER sequence is not SNMPv3")
    return {"snmp_version": version_number, "outer_message_parsed": True}


def ntp_request():
    packet = bytearray(48)
    packet[0] = (4 << 3) | 3  # NTP version 4, client mode
    packet[2] = 6             # Poll interval
    packet[3] = 0xec          # Precision -20
    seconds = int(time.time()) + 2208988800
    fraction = int((time.time() % 1) * (1 << 32))
    packet[40:48] = seconds.to_bytes(4, "big") + fraction.to_bytes(4, "big")
    return bytes(packet)


def probe(port, request, parser=None):
    result = {
        "port": port,
        "transport": "UDP",
        "request_hex": request.hex(),
        "timeout_seconds": TIMEOUT_SECONDS,
    }
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.settimeout(TIMEOUT_SECONDS)
    try:
        sock.sendto(request, (TARGET, port))
        result["request_sent"] = True
        try:
            response, peer = sock.recvfrom(65535)
            result.update({
                "status": "response_received",
                "peer": peer[0],
                "response_length": len(response),
                "response_hex": response.hex(),
            })
            if parser:
                try:
                    result["parsed"] = parser(response)
                    result["parser_status"] = "parsed"
                except Exception as exc:
                    result["parser_status"] = "unparsed"
                    result["parser_error"] = str(exc)
            else:
                if len(response) < 48:
                    raise ValueError("NTP response shorter than 48 bytes")
                first = response[0]
                result["parsed"] = {
                    "version": (first >> 3) & 7,
                    "mode": first & 7,
                    "leap_indicator": first >> 6,
                    "stratum": response[1],
                    "originate_timestamp_matches_request": response[24:32] == request[40:48],
                }
                valid = ((first & 7) == 4 and ((first >> 3) & 7) in (3, 4)
                         and response[24:32] == request[40:48])
                result["parser_status"] = "protocol_response" if valid else "response_not_confirmed_as_matching_ntp"
        except socket.timeout:
            result["status"] = "no_response_within_timeout"
            result["interpretation"] = "Silence is inconclusive; it does not establish that the port or service is absent."
    except OSError as exc:
        result.update({"status": "socket_error", "error": str(exc)})
    finally:
        sock.close()
    return result


ntp_packet = ntp_request()
snmp_packet = snmpv3_discovery_request()
results = [probe(123, ntp_packet), probe(161, snmp_packet, parse_snmpv3_response)]
for item in results:
    item["read_only_follow_up_supported"] = (
        item.get("parser_status") == "protocol_response"
        or item.get("parser_status") == "parsed"
    )

print(json.dumps({
    "target": TARGET,
    "purpose": "Validate reported open|filtered UDP ports with limited, non-invasive protocol requests.",
    "coverage": {
        "ports_attempted": [123, 161],
        "attempted_each_once": True,
        "limitations": "One UDP request per port; timeout, filtering, packet loss, and incomplete protocol parsing can leave service status unresolved. No credentials were guessed."
    },
    "observations": results,
    "student_session_verified": False
}, sort_keys=True))

