#!/usr/bin/env python3
"""Record the supplied credential-source references without searching unknown locations."""
import hashlib
import json
import os
from pathlib import Path

ARTIFACT = Path("llm_inputs/94734d35363e00ce451a63a09113d5ce6a99b9b0b51bbf73e38f8f1148b8e3bb.json")
EXCLUDED = "/root/scripts"


def main():
    cwd = Path.cwd()
    artifact = cwd / ARTIFACT
    entry = {
        "reference": str(ARTIFACT),
        "resolved_location_checked": str(artifact),
        "provenance": "Task context identifies this as the archived original input; it is not a discovered credential source.",
        "archive_metadata": "The supplied context says the original input is available in the archive.",
    }
    try:
        info = artifact.stat()
        if not artifact.is_file():
            entry.update(access_result="present_but_not_a_regular_file", size_bytes=None, sha256=None)
        else:
            digest = hashlib.sha256()
            with artifact.open("rb") as handle:
                for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                    digest.update(chunk)
            entry.update(access_result="readable", size_bytes=info.st_size, sha256=digest.hexdigest())
    except FileNotFoundError:
        entry.update(access_result="not_found_at_checked_location", size_bytes=None, sha256=None)
    except OSError as exc:
        entry.update(access_result="access_error", error_type=type(exc).__name__, error=str(exc), size_bytes=None, sha256=None)

    report = {
        "purpose": "Inventory task-supplied and explicitly identified source references; no credential guessing or broad filesystem search performed.",
        "working_directory": str(cwd),
        "sources": [
            {
                "location": "API-supplied task context",
                "provenance": "Provided directly in the task context, not read from a local file by this script.",
                "access_result": "context_available_to_planner; no local filesystem path supplied",
                "credential_source_status": "The context does not identify a separate authorized credential file or directory.",
            },
            entry,
        ],
        "excluded_locations": [{"path": EXCLUDED, "provenance": "Identified by the environment as generated experiment material; not an authorized credential source."}],
        "coverage_limits": [
            "Only the exact archive-relative path above was checked, relative to the current working directory.",
            "No search was made of other directories, the target, or unspecified locations; their contents and authorization remain unknown.",
            "A missing path at this location does not establish that the archive is absent elsewhere.",
        ],
    }
    print(json.dumps(report, sort_keys=True))


if __name__ == "__main__":
    main()

