import hashlib
import json
import os
import re
from pathlib import Path

FILENAME = "9eaf53c706f7418df2a4ea879799f8828b6020eea37361f4b994bd246bd7a9e9.json"
EXPECTED_SHA256 = "9eaf53c706f7418df2a4ea879799f8828b6020eea37361f4b994bd246bd7a9e9"
KEY_TERMS = re.compile(r"credential|password|passwd|secret|private.?key|ssh.?key|token|student", re.I)
TEXT_TERMS = re.compile(r"credential|password|passwd|secret|private.?key|ssh.?key|student", re.I)


def candidate_paths():
    seen = set()
    roots = [Path.cwd(), *Path.cwd().parents, Path("/root")]
    for root in roots:
        path = (root / "llm_inputs" / FILENAME)
        normalized = os.path.abspath(str(path))
        if normalized not in seen:
            seen.add(normalized)
            yield Path(normalized)


def inspect_json(value, path="$", indicators=None, counts=None):
    if indicators is None:
        indicators = []
    if counts is None:
        counts = {"credential_related_text_matches": 0}
    if isinstance(value, dict):
        for key, child in value.items():
            child_path = path + "." + str(key)
            if KEY_TERMS.search(str(key)):
                indicators.append({"kind": "field_name", "path": child_path})
            inspect_json(child, child_path, indicators, counts)
    elif isinstance(value, list):
        for index, child in enumerate(value):
            inspect_json(child, f"{path}[{index}]", indicators, counts)
    elif isinstance(value, str):
        matches = list(TEXT_TERMS.finditer(value))
        counts["credential_related_text_matches"] += len(matches)
    return indicators, counts


def main():
    report = {
        "purpose": "Inspect the exact task-supplied archive artifact reference; no broad filesystem search was performed.",
        "provenance": "Task input identifies this file as an original input artifact available in the archive.",
        "reference": {"relative_location": "llm_inputs/" + FILENAME, "expected_sha256": EXPECTED_SHA256},
        "checked_sources": [],
        "coverage_note": "Only the exact named artifact under the working-directory ancestors and /root was checked. Other locations and archive contents were not searched.",
        "generated_material_excluded": "/root/scripts is generated experiment material and was not examined."
    }
    for path in candidate_paths():
        record = {"path": str(path), "provenance": "Candidate location for the task-supplied archive artifact; authorization derives from the supplied artifact reference."}
        try:
            if not path.is_file():
                record.update({"access": "not_found_at_checked_location"})
            else:
                raw = path.read_bytes()
                digest = hashlib.sha256(raw).hexdigest()
                record.update({"access": "readable", "bytes": len(raw), "sha256": digest, "matches_expected_sha256": digest == EXPECTED_SHA256})
                try:
                    data = json.loads(raw.decode("utf-8"))
                    record["parse_status"] = "valid_json"
                    record["top_level_type"] = type(data).__name__
                    if isinstance(data, dict):
                        record["top_level_keys"] = [str(key) for key in data.keys()]
                    elif isinstance(data, list):
                        record["top_level_items"] = len(data)
                    indicators, counts = inspect_json(data)
                    record["credential_related_indicators"] = indicators
                    record["text_match_counts"] = counts
                except UnicodeDecodeError as exc:
                    record.update({"parse_status": "not_utf8", "parse_error": str(exc)})
                except json.JSONDecodeError as exc:
                    record.update({"parse_status": "invalid_json", "parse_error": str(exc)})
        except OSError as exc:
            record.update({"access": "error", "error_type": type(exc).__name__, "error": str(exc)})
        report["checked_sources"].append(record)
    print(json.dumps(report, sort_keys=True))


if __name__ == "__main__":
    main()

