import hashlib
import json
import os
import re
from pathlib import Path

RELATIVE_ARTIFACT = Path("llm_inputs/fbdca2dfe05cb6b3181656339df97a732665435606ed4eb756ac0fd10f1e5545.json")
EXPECTED_HASH = "fbdca2dfe05cb6b3181656339df97a732665435606ed4eb756ac0fd10f1e5545"
EXCLUDED_ROOT = Path("/root/scripts").resolve()


def is_within(path, root):
    try:
        path.relative_to(root)
        return True
    except ValueError:
        return False


def add_candidate(paths, candidate, label):
    try:
        resolved = candidate.resolve(strict=False)
    except OSError:
        resolved = candidate.absolute()
    if is_within(resolved, EXCLUDED_ROOT):
        return
    key = str(resolved)
    if key not in paths:
        paths[key] = {"path": key, "basis": [label]}
    else:
        paths[key]["basis"].append(label)


def redact(text):
    text = re.sub(
        r'(?i)("?(?:password|passwd|passphrase|secret|token|private[_ -]?key)"?\s*[:=]\s*)("?)[^\s,;"}]+',
        r'\1[REDACTED]', text,
    )
    return text[:320]


def walk_strings(value, location="$", depth=0):
    if depth > 20:
        return
    if isinstance(value, dict):
        for key, child in value.items():
            yield from walk_strings(child, location + "." + str(key), depth + 1)
    elif isinstance(value, list):
        for index, child in enumerate(value):
            yield from walk_strings(child, location + "[" + str(index) + "]", depth + 1)
    elif isinstance(value, str):
        yield location, value


def main():
    candidates = {}
    cwd = Path.cwd()
    add_candidate(candidates, cwd / RELATIVE_ARTIFACT, "relative to current working directory")
    add_candidate(candidates, Path("/root") / RELATIVE_ARTIFACT, "under /root")
    add_candidate(candidates, Path("/workspace") / RELATIVE_ARTIFACT, "under /workspace")
    add_candidate(candidates, Path("/") / RELATIVE_ARTIFACT, "under filesystem root")

    checked = []
    found = None
    for item in candidates.values():
        path = Path(item["path"])
        record = dict(item)
        try:
            if not path.is_file():
                record["status"] = "not_found_or_not_a_regular_file"
            else:
                data = path.read_bytes()
                record["status"] = "readable"
                record["size_bytes"] = len(data)
                record["sha256"] = hashlib.sha256(data).hexdigest()
                record["matches_expected_hash"] = record["sha256"] == EXPECTED_HASH
                found = (path, data, record)
        except OSError as exc:
            record["status"] = "access_error"
            record["error"] = str(exc)
        checked.append(record)

    result = {
        "purpose": "Inspect only the exact task-provided original-input artifact; no target interaction, credential guessing, or embedded-code execution.",
        "requested_artifact": str(RELATIVE_ARTIFACT),
        "expected_sha256": EXPECTED_HASH,
        "provenance_basis": "The node metadata names this exact archive artifact. The supplied _input_context.original_input separately names 1384d9464ec6269c378d7a7c7aef45988e9a5c75ec823da7244f2fce9b7ac4d9.json, so the metadata is inconsistent; this check follows the node's explicit artifact identifier and does not conflate the two.",
        "candidate_paths_checked": checked,
        "coverage": "Checked the exact relative path under the current working directory, /root, /workspace, and filesystem root. Paths resolving inside /root/scripts were excluded as generated material. No other archive locations were searched.",
    }

    if found is None:
        result["artifact_observation"] = "The exact artifact was not readable at the candidate paths checked. Its contents and whether it identifies an authorized source remain unknown."
    else:
        path, data, record = found
        artifact = {"path": str(path), "read_result": "readable", "size_bytes": len(data), "sha256": record["sha256"], "matches_expected_hash": record["matches_expected_hash"]}
        try:
            parsed = json.loads(data.decode("utf-8"))
            artifact["parse_status"] = "valid_json"
            artifact["top_level_type"] = type(parsed).__name__
            artifact["top_level_keys"] = list(parsed.keys())[:100] if isinstance(parsed, dict) else None
            matches = []
            terms = re.compile(r"student|credential|authori[sz]|source|ssh|private.?key|password|passphrase|secret|token|\buser\b", re.I)
            for location, text in walk_strings(parsed):
                if terms.search(text):
                    matches.append({"location": location, "indicator_excerpt": redact(text.strip())})
                    if len(matches) >= 100:
                        break
            artifact["relevant_string_indicators"] = matches
            artifact["indicator_coverage"] = "Recursively inspected parsed JSON string values (maximum depth 20); returned at most 100 matching values. Indicators require contextual review and do not by themselves establish authorization or a usable credential."
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            artifact["parse_status"] = "failed"
            artifact["parse_error"] = str(exc)
            artifact["content_review"] = "Contents could not be reviewed as UTF-8 JSON; no conclusion about authorized sources is supported."
        result["artifact_observation"] = artifact

    print(json.dumps(result, ensure_ascii=False, sort_keys=True))


if __name__ == "__main__":
    main()

