import hashlib
import json
import os
import sys

IDENTITIES = [
    {
        "label": "task_spec_identity",
        "path": "llm_inputs/2614cb20a5111a1dfc405b1b04803d3f39d8d1419d50d622e38009ede9fc8dca.json",
        "sha256": "2614cb20a5111a1dfc405b1b04803d3f39d8d1419d50d622e38009ede9fc8dca",
    },
    {
        "label": "original_input_metadata_identity",
        "path": "llm_inputs/11e5428a7c633eb01f149b4c7a14e54a6ffa7310200a3d1ef74f197f90a60b78.json",
        "sha256": "11e5428a7c633eb01f149b4c7a14e54a6ffa7310200a3d1ef74f197f90a60b78",
    },
]

SKIP_DIRS = {
    "/proc", "/sys", "/dev", "/run", "/root/scripts",
}


def discover_files():
    found = set()
    errors = []
    cwd = os.path.abspath(os.getcwd())

    # Check the supplied relative paths from the actual working directory first.
    for identity in IDENTITIES:
        direct = os.path.abspath(os.path.join(cwd, identity["path"]))
        if os.path.isfile(direct):
            found.add(direct)

    # Search for these exact basenames across the mounted filesystem, excluding
    # virtual filesystems and the known generated-action directory.
    wanted = {os.path.basename(item["path"]) for item in IDENTITIES}
    for root, dirs, files in os.walk("/", topdown=True, followlinks=False):
        dirs[:] = [name for name in dirs
                   if os.path.join(root, name) not in SKIP_DIRS
                   and not os.path.join(root, name).startswith("/proc/")
                   and not os.path.join(root, name).startswith("/sys/")
                   and not os.path.join(root, name).startswith("/dev/")
                   and not os.path.join(root, name).startswith("/run/")
                   and not os.path.join(root, name).startswith("/root/scripts/")]
        for name in files:
            if name in wanted:
                found.add(os.path.abspath(os.path.join(root, name)))

    return sorted(found), errors


def inspect(path, expected_hash):
    record = {"path": path, "access": "unknown"}
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except OSError as exc:
        record.update({"access": "error", "error": str(exc)})
        return record

    actual = hashlib.sha256(raw).hexdigest()
    matches = actual.lower() == expected_hash.lower()
    record.update({
        "access": "readable",
        "size_bytes": len(raw),
        "sha256": actual,
        "expected_sha256": expected_hash,
        "sha256_matches": matches,
    })
    if not matches:
        record["content_status"] = "not_parsed_identity_mismatch"
        return record

    try:
        text = raw.decode("utf-8")
        parsed = json.loads(text)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        record.update({"content_status": "uninterpretable", "parse_error": str(exc)})
        return record

    record.update({"content_status": "parsed_json", "contents": parsed})
    return record


def main():
    locations, search_errors = discover_files()
    result = {
        "purpose": "Verify only the separately supplied artifact identities; do not substitute between them.",
        "working_directory": os.getcwd(),
        "identity_conflict": IDENTITIES[0]["sha256"] != IDENTITIES[1]["sha256"],
        "identities": [],
        "search": {
            "method": "Exact supplied relative paths plus recursive exact-basename search under /",
            "excluded": sorted(SKIP_DIRS),
            "candidate_paths": locations,
            "errors": search_errors,
            "coverage_note": "Filesystem walk excludes virtual filesystems and /root/scripts; archive members not materialized as files are not inspected.",
        },
    }

    for identity in IDENTITIES:
        expected_path = os.path.abspath(identity["path"])
        matching_names = [p for p in locations if os.path.basename(p) == os.path.basename(identity["path"])]
        candidates = sorted(set([expected_path] + matching_names))
        result["identities"].append({
            "label": identity["label"],
            "supplied_path": identity["path"],
            "supplied_sha256": identity["sha256"],
            "candidate_results": [inspect(path, identity["sha256"]) for path in candidates],
        })

    print(json.dumps(result, ensure_ascii=False, sort_keys=True))


if __name__ == "__main__":
    main()

