import hashlib
import json
import os
import tarfile
import zipfile
from datetime import datetime, timezone

TARGET_PATH = "llm_inputs/2614cb20a5111a1dfc405b1b04803d3f39d8d1419d50d622e38009ede9fc8dca.json"
EXPECTED_SHA256 = "2614cb20a5111a1dfc405b1b04803d3f39d8d1419d50d622e38009ede9fc8dca"
EXCLUDED_DIRS = {"/dev", "/proc", "/sys", "/run", "/root/scripts"}
ARCHIVE_SUFFIXES = (
    ".zip", ".tar", ".tar.gz", ".tgz", ".tar.bz2", ".tbz2",
    ".tar.xz", ".txz", ".7z", ".rar"
)
CHUNK_SIZE = 1024 * 1024


def digest_stream(stream):
    digest = hashlib.sha256()
    size = 0
    while True:
        chunk = stream.read(CHUNK_SIZE)
        if not chunk:
            break
        digest.update(chunk)
        size += len(chunk)
    return digest.hexdigest(), size


def archive_provenance(path):
    result = {"path": path}
    try:
        st = os.stat(path)
        result.update({
            "size_bytes": st.st_size,
            "modified_utc": datetime.fromtimestamp(st.st_mtime, timezone.utc).isoformat(),
        })
        with open(path, "rb") as f:
            result["archive_file_sha256"], _ = digest_stream(f)
    except OSError as exc:
        result["provenance_error"] = str(exc)
    return result


def candidate_paths():
    found = []
    walk_errors = []

    def onerror(exc):
        walk_errors.append({"path": getattr(exc, "filename", None), "error": str(exc)})

    for root, dirs, files in os.walk("/", topdown=True, followlinks=False, onerror=onerror):
        dirs[:] = [d for d in dirs if os.path.join(root, d) not in EXCLUDED_DIRS]
        for name in files:
            lower = name.lower()
            if lower.endswith(ARCHIVE_SUFFIXES):
                found.append(os.path.join(root, name))
    return sorted(set(found)), walk_errors


def inspect_zip(path):
    matches = []
    same_basename = []
    with zipfile.ZipFile(path, "r") as archive:
        for info in archive.infolist():
            if info.is_dir():
                continue
            if info.filename == TARGET_PATH or os.path.basename(info.filename) == os.path.basename(TARGET_PATH):
                record = {"member_path": info.filename, "member_size_bytes": info.file_size}
                try:
                    with archive.open(info, "r") as stream:
                        record["sha256"], observed_size = digest_stream(stream)
                    record["observed_size_bytes"] = observed_size
                    record["identity_matches"] = (
                        info.filename == TARGET_PATH and record["sha256"] == EXPECTED_SHA256
                    )
                except Exception as exc:
                    record["read_error"] = str(exc)
                    record["identity_matches"] = False
                if info.filename == TARGET_PATH:
                    matches.append(record)
                else:
                    same_basename.append(record)
    return matches, same_basename


def inspect_tar(path):
    matches = []
    same_basename = []
    with tarfile.open(path, mode="r:*") as archive:
        for member in archive.getmembers():
            if not member.isfile():
                continue
            if member.name == TARGET_PATH or os.path.basename(member.name) == os.path.basename(TARGET_PATH):
                record = {"member_path": member.name, "member_size_bytes": member.size}
                try:
                    stream = archive.extractfile(member)
                    if stream is None:
                        raise OSError("archive member has no readable stream")
                    with stream:
                        record["sha256"], observed_size = digest_stream(stream)
                    record["observed_size_bytes"] = observed_size
                    record["identity_matches"] = (
                        member.name == TARGET_PATH and record["sha256"] == EXPECTED_SHA256
                    )
                except Exception as exc:
                    record["read_error"] = str(exc)
                    record["identity_matches"] = False
                if member.name == TARGET_PATH:
                    matches.append(record)
                else:
                    same_basename.append(record)
    return matches, same_basename


def main():
    paths, walk_errors = candidate_paths()
    archives = []
    for path in paths:
        result = {"provenance": archive_provenance(path)}
        try:
            if zipfile.is_zipfile(path):
                result["format"] = "zip"
                result["exact_member_matches"], result["same_basename_nonexact_members"] = inspect_zip(path)
            elif tarfile.is_tarfile(path):
                result["format"] = "tar"
                result["exact_member_matches"], result["same_basename_nonexact_members"] = inspect_tar(path)
            else:
                result["format"] = "unrecognized_or_unsupported"
                result["inspection_note"] = "Candidate suffix found, but Python standard-library ZIP/TAR readers did not recognize it."
        except Exception as exc:
            result["inspection_error"] = str(exc)
        archives.append(result)

    exact_found = any(a.get("exact_member_matches") for a in archives)
    exact_verified = any(
        m.get("identity_matches")
        for a in archives for m in a.get("exact_member_matches", [])
    )
    print(json.dumps({
        "purpose": "Inspect archives for the exact requested artifact; do not substitute a differently identified artifact.",
        "requested_identity": {"member_path": TARGET_PATH, "sha256": EXPECTED_SHA256},
        "search": {
            "method": "Recursive filesystem walk for common archive suffixes; generated-action directory and virtual filesystems excluded.",
            "excluded_paths": sorted(EXCLUDED_DIRS),
            "archive_candidates_found": len(paths),
            "walk_errors": walk_errors,
        },
        "archives": archives,
        "exact_member_found": exact_found,
        "exact_identity_verified": exact_verified,
        "coverage_note": "ZIP and TAR archives with recognized suffixes were examined. Unsupported archive formats, inaccessible paths, excluded paths, and archive types without these suffixes may not have been inspected. Same-basename non-exact members are not substitutes.",
    }, sort_keys=True))


if __name__ == "__main__":
    main()

