import os
import sys
import json
import hashlib
import zipfile
import tarfile
import stat
from pathlib import Path

REQUESTED_PATH = "llm_inputs/2614cb20a5111a1dfc405b1b04803d3f39d8d1419d50d622e38009ede9fc8dca.json"
REQUESTED_SHA256 = "2614cb20a5111a1dfc405b1b04803d3f39d8d1419d50d622e38009ede9fc8dca"
ARCHIVE_SUFFIXES = (".zip", ".tar", ".tgz", ".tar.gz", ".tbz", ".tbz2", ".tar.bz2", ".txz", ".tar.xz", ".7z", ".rar")
META_SUFFIXES = {".json", ".yaml", ".yml", ".toml", ".txt", ".manifest", ".meta", ".ini", ".cfg"}
SKIP_DIRS = {"proc", "sys", "dev", "run", "node_modules", ".git"}


def is_archive_name(name):
    lower = name.lower()
    return any(lower.endswith(suffix) for suffix in ARCHIVE_SUFFIXES)


def collect_strings(obj, out):
    if isinstance(obj, dict):
        for key, value in obj.items():
            collect_strings(key, out)
            collect_strings(value, out)
    elif isinstance(obj, (list, tuple)):
        for value in obj:
            collect_strings(value, out)
    elif isinstance(obj, str):
        out.append(obj)


def archive_paths_from_text(path, text):
    found = set()
    try:
        parsed = json.loads(text)
        strings = []
        collect_strings(parsed, strings)
    except Exception:
        strings = [text]
    for value in strings:
        value = value.strip().strip("\"' ")
        if not value:
            continue
        for token in value.replace("\\", " ").split():
            token = token.strip("\"' ,;()[]{}")
            if is_archive_name(token):
                p = Path(token)
                if not p.is_absolute():
                    p = path.parent / p
                found.add(str(p))
        p = Path(value)
        if is_archive_name(p.name):
            if not p.is_absolute():
                p = path.parent / p
            found.add(str(p))
    return found


def inspect_archive(path):
    result = {"path": str(path), "status": "unrecognized_or_unsupported"}
    try:
        st = path.stat()
        if not stat.S_ISREG(st.st_mode):
            result["status"] = "not_regular_file"
            return result
        result["provenance"] = {
            "size_bytes": st.st_size,
            "modified_utc": __import__("datetime").datetime.fromtimestamp(
                st.st_mtime, __import__("datetime").timezone.utc
            ).isoformat(),
            "archive_file_sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
        }
        members = []
        try:
            with zipfile.ZipFile(path, "r") as archive:
                result["format"] = "zip"
                for info in archive.infolist():
                    if info.filename == REQUESTED_PATH:
                        data = archive.read(info)
                        members.append({"member_path": info.filename, "sha256": hashlib.sha256(data).hexdigest(), "size_bytes": len(data), "content_utf8": data.decode("utf-8", errors="replace")})
        except (zipfile.BadZipFile, OSError, EOFError):
            pass
        if not result.get("format"):
            try:
                with tarfile.open(path, "r:*") as archive:
                    result["format"] = "tar"
                    for info in archive.getmembers():
                        if info.name == REQUESTED_PATH and info.isfile():
                            stream = archive.extractfile(info)
                            if stream is not None:
                                data = stream.read()
                                members.append({"member_path": info.name, "sha256": hashlib.sha256(data).hexdigest(), "size_bytes": len(data), "content_utf8": data.decode("utf-8", errors="replace")})
            except (tarfile.TarError, OSError, EOFError):
                pass
        if result.get("format"):
            result["status"] = "inspected"
            result["exact_member_matches"] = [m for m in members if m["sha256"] == REQUESTED_SHA256]
            result["exact_member_found"] = bool(members)
            result["exact_identity_verified"] = bool(result["exact_member_matches"])
            result["exact_member_observations"] = members
    except Exception as exc:
        result["error"] = f"{type(exc).__name__}: {exc}"
    return result


def main():
    roots = []
    for env_name, value in os.environ.items():
        if any(word in env_name.lower() for word in ("task", "input", "stage", "artifact", "archive")) and value:
            candidate = Path(value).expanduser()
            if candidate.is_dir():
                roots.append(candidate)
            elif candidate.exists():
                roots.append(candidate.parent)
    roots.extend([Path.cwd(), Path("/tmp"), Path("/var/tmp"), Path("/mnt/data"), Path("/workspace"), Path("/input"), Path("/task"), Path("/root")])
    unique_roots = []
    seen_roots = set()
    for root in roots:
        try:
            resolved = root.resolve()
        except OSError:
            resolved = root.absolute()
        key = str(resolved)
        if key not in seen_roots and resolved.exists() and resolved.is_dir():
            seen_roots.add(key)
            unique_roots.append(resolved)

    metadata_hits = []
    archive_candidates = set()
    errors = []
    visited_files = 0
    visited_dirs = 0
    for root in unique_roots:
        if root.is_file():
            continue
        for current, dirs, files in os.walk(root, topdown=True, followlinks=False):
            current_path = Path(current)
            dirs[:] = [d for d in dirs if d not in SKIP_DIRS and not (current_path == Path("/root") and d == "scripts")]
            visited_dirs += 1
            for name in files:
                p = current_path / name
                try:
                    if is_archive_name(name):
                        archive_candidates.add(str(p))
                        continue
                    suffix = p.suffix.lower()
                    likely_metadata = suffix in META_SUFFIXES and any(term in (name + " " + str(p.parent)).lower() for term in ("task", "input", "stage", "manifest", "archive", "artifact", "meta", "llm_inputs"))
                    if not likely_metadata:
                        continue
                    data = p.read_bytes()
                    visited_files += 1
                    if REQUESTED_SHA256.encode() not in data and REQUESTED_PATH.encode() not in data:
                        continue
                    text = data.decode("utf-8", errors="replace")
                    refs = archive_paths_from_text(p, text)
                    metadata_hits.append({"path": str(p), "contains_requested_path": REQUESTED_PATH in text, "contains_requested_sha256": REQUESTED_SHA256 in text, "archive_references": sorted(refs), "matching_text_excerpt": text[:12000]})
                    archive_candidates.update(refs)
                except (OSError, PermissionError) as exc:
                    errors.append({"path": str(p), "error": f"{type(exc).__name__}: {exc}"})

    archive_results = []
    for candidate in sorted(archive_candidates):
        p = Path(candidate).expanduser()
        if not p.is_absolute():
            p = Path.cwd() / p
        try:
            if p.exists() and p.is_file():
                archive_results.append(inspect_archive(p))
        except OSError as exc:
            archive_results.append({"path": str(p), "status": "inaccessible", "error": f"{type(exc).__name__}: {exc}"})

    output = {
        "purpose": "Locate and inspect the task-designated archive for one exact member identity; the distinct original_input artifact is not a substitute.",
        "requested_identity": {"member_path": REQUESTED_PATH, "sha256": REQUESTED_SHA256},
        "search": {"roots_searched": [str(p) for p in unique_roots], "directories_visited": visited_dirs, "metadata_files_read": visited_files, "metadata_hits": metadata_hits, "archive_candidates_checked": len(archive_results), "walk_or_access_errors": errors},
        "archives": archive_results,
        "coverage_note": "Search was limited to existing task/input/staging-oriented environment paths and the listed common staging roots. Generated action directory /root/scripts and virtual filesystem directories were excluded. Unreferenced nonstandard archive names, archive types not supported by Python's standard library, paths outside these roots, and inaccessible locations may remain unexamined. A matching hash verifies bytes at the exact member path, not by itself the archive's designation; designation depends on task metadata references."
    }
    print(json.dumps(output, ensure_ascii=False, sort_keys=True))


if __name__ == "__main__":
    main()

