import os
import re
import json
import hashlib
import tarfile
import zipfile
from pathlib import Path

MEMBER = "llm_inputs/2614cb20a5111a1dfc405b1b04803d3f39d8d1419d50d622e38009ede9fc8dca.json"
EXPECTED = "2614cb20a5111a1dfc405b1b04803d3f39d8d1419d50d622e38009ede9fc8dca"
PRIOR_ROOTS = {"/root", "/root/scripts", "/tmp", "/var/tmp"}
TEXT_SUFFIXES = {".json", ".yaml", ".yml", ".toml", ".txt", ".md", ".xml", ".csv", ".ini"}
KEYWORDS = ("task", "input", "stage", "manifest", "llm")
ARCHIVE_RE = re.compile(r"(?i)(?:[A-Za-z0-9_./~@+ -]+?\.(?:tar\.gz|tar\.bz2|tar\.xz|tgz|tbz2|txz|zip|tar|7z|rar))")


def is_under(path, parent):
    try:
        return os.path.commonpath((os.path.realpath(path), os.path.realpath(parent))) == os.path.realpath(parent)
    except (ValueError, OSError):
        return False


def relevant_component(path):
    return any(k in os.path.basename(path).lower() for k in KEYWORDS)


def is_text_candidate(path, in_relevant_tree):
    name = os.path.basename(path).lower()
    return ("manifest" in name or "task" in name or "input" in name or
            (in_relevant_tree and Path(name).suffix.lower() in TEXT_SUFFIXES))

# Search new task-input/staging-oriented areas, not the roots reported by the
# preceding locator. Known staging/data roots are included when present; other
# top-level task/input/staging-like directories are discovered from '/'.
roots = ["/workspace", "/workspaces", "/mnt/data", "/mnt/input", "/mnt/inputs",
         "/mnt/staging", "/data", "/input", "/inputs", "/staging", "/tasks",
         "/task", "/var/task", "/opt/task", "/srv/task", "/home"]
root_listing_errors = []
try:
    for entry in os.scandir("/"):
        try:
            if entry.is_dir(follow_symlinks=False) and relevant_component(entry.path):
                roots.append(entry.path)
        except OSError as exc:
            root_listing_errors.append({"path": entry.path, "error": str(exc)})
except OSError as exc:
    root_listing_errors.append({"path": "/", "error": str(exc)})

roots = sorted({os.path.realpath(r) for r in roots if os.path.isdir(r)
                and not any(is_under(r, p) or is_under(p, r) for p in PRIOR_ROOTS)})
examined_dirs = []
examined_files = []
errors = list(root_listing_errors)
references = []
seen_files = set()

# Traverse data roots for task/input/staging descendants. In broad roots such as
# /home and /mnt/data, avoid unrelated hidden/cache trees; preserve coverage notes.
for root in roots:
    try:
        for current, dirs, files in os.walk(root, topdown=True, followlinks=False):
            if any(is_under(current, p) or is_under(p, current) for p in PRIOR_ROOTS):
                dirs[:] = []
                continue
            depth = len(Path(current).relative_to(root).parts)
            if depth >= 7:
                dirs[:] = []
            else:
                dirs[:] = [d for d in dirs if not d.startswith(".") and d not in {
                    "proc", "sys", "dev", "node_modules", "__pycache__", ".git", "cache", "caches"
                }]
            examined_dirs.append(current)
            tree_relevant = any(relevant_component(part) for part in Path(current).parts)
            for name in files:
                path = os.path.join(current, name)
                if not is_text_candidate(path, tree_relevant):
                    continue
                real = os.path.realpath(path)
                if real in seen_files or any(is_under(real, p) for p in PRIOR_ROOTS):
                    continue
                seen_files.add(real)
                try:
                    if os.path.getsize(real) > 8 * 1024 * 1024:
                        errors.append({"path": real, "error": "skipped: text candidate exceeds 8 MiB inspection limit"})
                        continue
                    with open(real, "rb") as fh:
                        raw = fh.read()
                    text = raw.decode("utf-8")
                    examined_files.append(real)
                except (OSError, UnicodeError) as exc:
                    errors.append({"path": real, "error": str(exc)})
                    continue

                # A manifest is a designation reference only when it names an
                # archive path; matching identity strings alone do not designate one.
                archive_paths = set()
                for match in ARCHIVE_RE.finditer(text):
                    candidate = match.group(0).strip().strip("\\\"'` ,;:()[]{}")
                    if candidate:
                        archive_paths.add(candidate)
                try:
                    parsed = json.loads(text)
                except (json.JSONDecodeError, ValueError):
                    parsed = None

                def collect_archive_values(obj, key=""):
                    if isinstance(obj, dict):
                        for k, v in obj.items():
                            collect_archive_values(v, str(k).lower())
                    elif isinstance(obj, list):
                        for v in obj:
                            collect_archive_values(v, key)
                    elif isinstance(obj, str):
                        val = obj.strip()
                        if "archive" in key and val:
                            archive_paths.add(val)
                        if ARCHIVE_RE.search(val):
                            for m in ARCHIVE_RE.finditer(val):
                                archive_paths.add(m.group(0).strip().strip("\\\"'` ,;:()[]{}"))

                if parsed is not None:
                    collect_archive_values(parsed)
                if archive_paths:
                    references.append({"source_path": real, "archive_references": sorted(archive_paths),
                                       "mentions_requested_member": MEMBER in text,
                                       "mentions_requested_sha256": EXPECTED in text})
            # Record walk errors delivered by os.walk via onerror separately below.
    except OSError as exc:
        errors.append({"path": root, "error": str(exc)})

# Resolve and inspect only archives named by a task-input/staging manifest.
archive_results = []
archive_paths_seen = set()
for ref in references:
    for named in ref["archive_references"]:
        if not named or named in archive_paths_seen:
            continue
        archive_paths_seen.add(named)
        expanded = os.path.expanduser(os.path.expandvars(named))
        possibilities = [expanded] if os.path.isabs(expanded) else [
            os.path.join(os.path.dirname(ref["source_path"]), expanded), expanded
        ]
        resolved = next((os.path.realpath(p) for p in possibilities if os.path.isfile(p)), None)
        result = {"reference_source": ref["source_path"], "referenced_path": named,
                  "resolved_path": resolved, "member_path": MEMBER}
        if resolved is None:
            result["inspection_error"] = "referenced archive path did not resolve to a readable regular file"
            archive_results.append(result)
            continue
        if any(is_under(resolved, p) for p in PRIOR_ROOTS):
            result["inspection_error"] = "resolved path is in a previously searched or excluded root; not re-inspected"
            archive_results.append(result)
            continue
        try:
            payload = None
            if zipfile.is_zipfile(resolved):
                with zipfile.ZipFile(resolved, "r") as zf:
                    names = zf.namelist()
                    if MEMBER in names:
                        payload = zf.read(MEMBER)
            elif tarfile.is_tarfile(resolved):
                with tarfile.open(resolved, "r:*") as tf:
                    item = tf.getmember(MEMBER) if MEMBER in tf.getnames() else None
                    if item is not None and item.isfile():
                        stream = tf.extractfile(item)
                        if stream is not None:
                            payload = stream.read()
            else:
                result["inspection_error"] = "referenced archive format is not supported by Python standard-library zipfile/tarfile"
            if payload is not None:
                digest = hashlib.sha256(payload).hexdigest()
                result.update({"member_found": True, "member_size_bytes": len(payload),
                               "member_sha256": digest, "sha256_matches_requested": digest == EXPECTED,
                               "member_readable": True})
                try:
                    obj = json.loads(payload.decode("utf-8"))
                    result["member_json_readable"] = True
                    result["member_top_level_type"] = type(obj).__name__
                    if isinstance(obj, dict):
                        result["member_top_level_keys"] = sorted(str(k) for k in obj.keys())
                except (UnicodeError, json.JSONDecodeError, ValueError) as exc:
                    result["member_json_readable"] = False
                    result["member_parse_error"] = str(exc)
            elif "inspection_error" not in result:
                result.update({"member_found": False, "member_readable": False,
                               "note": "exact member path not present as a regular file"})
        except (OSError, tarfile.TarError, zipfile.BadZipFile, KeyError, EOFError) as exc:
            result["inspection_error"] = str(exc)
        archive_results.append(result)

print(json.dumps({
    "purpose": "Search additional task-input references and staging locations for a designated archive; verify only the exact requested member identity.",
    "requested_identity": {"member_path": MEMBER, "sha256": EXPECTED},
    "prior_locator_roots_not_repeated": sorted(PRIOR_ROOTS),
    "roots_searched": roots,
    "directories_visited": len(examined_dirs),
    "manifest_like_files_read": len(examined_files),
    "files_examined": examined_files,
    "archive_references": references,
    "referenced_archive_checks": archive_results,
    "access_or_coverage_errors": errors,
    "coverage_notes": [
        "Traversal is limited to the listed and discovered task/input/staging-oriented roots; it is not a global filesystem search.",
        "Hidden/cache directories and paths at depth 7 or greater are not traversed.",
        "Only manifest-like or supported text files are read; candidates over 8 MiB and non-UTF-8 files are not inspected.",
        "Only archive formats supported by Python's standard library (ZIP and tar variants) can be checked; no unreferenced archive is treated as designated."
    ]
}, sort_keys=True))

