import hashlib
import json
import os
import re
import tarfile
import zipfile
from pathlib import Path

MEMBER = "llm_inputs/2614cb20a5111a1dfc405b1b04803d3f39d8d1419d50d622e38009ede9fc8dca.json"
EXPECTED_SHA256 = "2614cb20a5111a1dfc405b1b04803d3f39d8d1419d50d622e38009ede9fc8dca"
EXCLUDED = ("/root", "/root/scripts", "/tmp", "/var/tmp", "/home")
SKIP_NAMES = {"proc", "sys", "dev", "usr", "bin", "sbin", "lib", "lib64", "etc", "run/lock", "lost+found"}
TEXT_SUFFIXES = {".json", ".jsonl", ".yaml", ".yml", ".toml", ".ini", ".cfg", ".conf", ".txt", ".md", ".xml", ".csv"}
ARCHIVE_SUFFIXES = (".tar.gz", ".tgz", ".tar.bz2", ".tbz2", ".tar.xz", ".txz", ".tar", ".zip")
TASK_WORDS = re.compile(r"task|input|staging|stage|artifact|benchmark|manifest|workspace|autopen", re.I)
ARCHIVE_RE = re.compile(r"(?<![A-Za-z0-9_.-])(?:[A-Za-z0-9_./~@+-]+\.(?:tar\.gz|tgz|tar\.bz2|tbz2|tar\.xz|txz|tar|zip))(?![A-Za-z0-9_.-])", re.I)
MANIFEST_NAME = re.compile(r"manifest|task|input|stage|artifact|metadata|context|locator|index", re.I)


def is_excluded(path):
    path = os.path.abspath(path)
    return any(path == root or path.startswith(root + os.sep) for root in EXCLUDED)


def archive_digest(path):
    """Return exact requested member metadata using only stdlib ZIP/tar support."""
    try:
        if zipfile.is_zipfile(path):
            with zipfile.ZipFile(path) as zf:
                names = zf.namelist()
                if MEMBER not in names:
                    return {"archive": path, "status": "member_absent", "member_path": MEMBER}
                digest = hashlib.sha256()
                with zf.open(MEMBER) as stream:
                    for chunk in iter(lambda: stream.read(1024 * 1024), b""):
                        digest.update(chunk)
                actual = digest.hexdigest()
        elif tarfile.is_tarfile(path):
            with tarfile.open(path, "r:*") as tf:
                item = tf.getmember(MEMBER)
                stream = tf.extractfile(item)
                if stream is None:
                    return {"archive": path, "status": "member_not_readable", "member_path": MEMBER}
                digest = hashlib.sha256()
                with stream:
                    for chunk in iter(lambda: stream.read(1024 * 1024), b""):
                        digest.update(chunk)
                actual = digest.hexdigest()
        else:
            return {"archive": path, "status": "unsupported_or_not_archive"}
        return {"archive": path, "status": "checked", "member_path": MEMBER,
                "sha256": actual, "expected_sha256": EXPECTED_SHA256,
                "verified": actual == EXPECTED_SHA256}
    except KeyError:
        return {"archive": path, "status": "member_absent", "member_path": MEMBER}
    except (OSError, tarfile.TarError, zipfile.BadZipFile, RuntimeError) as exc:
        return {"archive": path, "status": "error", "error": f"{type(exc).__name__}: {exc}"}


def main():
    errors = []
    examined = []
    relevant_dirs = set()
    files_to_read = set()
    visited = set()
    requested_roots = ["/opt", "/mnt", "/media", "/srv", "/workspace", "/workspaces",
                       "/work", "/data", "/app", "/var/lib", "/var/cache"]
    # Include existing top-level directories whose names indicate task or staging material.
    try:
        with os.scandir("/") as entries:
            for entry in entries:
                if entry.is_dir(follow_symlinks=False) and TASK_WORDS.search(entry.name):
                    requested_roots.append(entry.path)
    except OSError as exc:
        errors.append({"path": "/", "error": f"{type(exc).__name__}: {exc}"})
    roots = []
    for root in requested_roots:
        root = os.path.abspath(root)
        if root not in roots and os.path.isdir(root) and not is_excluded(root):
            roots.append(root)

    for root in roots:
        for current, dirs, filenames in os.walk(root, topdown=True, followlinks=False, onerror=lambda e: errors.append({"path": getattr(e, "filename", root), "error": f"{type(e).__name__}: {e}"})):
            current = os.path.abspath(current)
            if is_excluded(current):
                dirs[:] = []
                continue
            visited.add(current)
            if TASK_WORDS.search(os.path.basename(current)):
                relevant_dirs.add(current)
            kept = []
            for name in dirs:
                child = os.path.join(current, name)
                if name in SKIP_NAMES or is_excluded(child):
                    continue
                # Avoid traversing runtime lock directories and virtual filesystems.
                if child == "/run/lock":
                    continue
                kept.append(name)
            dirs[:] = kept
            for name in filenames:
                path = os.path.join(current, name)
                suffix = Path(name).suffix.lower()
                if suffix in TEXT_SUFFIXES and (MANIFEST_NAME.search(name) or current in relevant_dirs or any(TASK_WORDS.search(part) for part in Path(current).parts)):
                    files_to_read.add(path)
                if TASK_WORDS.search(name):
                    relevant_dirs.add(current)
                    if suffix in TEXT_SUFFIXES:
                        files_to_read.add(path)

    # A directory name discovered from a filename applies to files in that directory too.
    for directory in list(relevant_dirs):
        try:
            with os.scandir(directory) as entries:
                for entry in entries:
                    if entry.is_file(follow_symlinks=False) and Path(entry.name).suffix.lower() in TEXT_SUFFIXES:
                        files_to_read.add(entry.path)
        except OSError as exc:
            errors.append({"path": directory, "error": f"{type(exc).__name__}: {exc}"})

    references = []
    for path in sorted(files_to_read):
        if is_excluded(path):
            continue
        try:
            with open(path, "r", encoding="utf-8") as stream:
                text = stream.read()
            examined.append({"path": path, "provenance": "filesystem text file; not under excluded generated-script roots"})
            for raw in ARCHIVE_RE.findall(text):
                ref = raw.strip("\"'(),;[]{}<> ")
                references.append({"source_file": path, "reference": ref})
        except (OSError, UnicodeError) as exc:
            errors.append({"path": path, "error": f"{type(exc).__name__}: {exc}"})

    checks = []
    seen_refs = set()
    for ref in references:
        source = ref["source_file"]
        value = ref["reference"]
        key = (source, value)
        if key in seen_refs:
            continue
        seen_refs.add(key)
        candidates = [value] if os.path.isabs(value) else [os.path.join(os.path.dirname(source), value), os.path.abspath(value)]
        unique = list(dict.fromkeys(os.path.abspath(p) for p in candidates))
        existing = [p for p in unique if os.path.isfile(p)]
        if not existing:
            checks.append({"source_file": source, "reference": value, "status": "referenced_archive_not_found_at_resolved_paths", "resolved_paths_checked": unique})
        else:
            for archive in existing:
                result = archive_digest(archive)
                result.update({"source_file": source, "reference": value})
                checks.append(result)

    result = {
        "purpose": "Discover task-input or staging locations outside previously searched roots and inspect task-input references; verify only the exact requested archive member identity.",
        "previously_searched_roots_not_repeated": list(EXCLUDED),
        "roots_searched": roots,
        "directories_visited": len(visited),
        "task_oriented_directories": sorted(relevant_dirs),
        "reference_files_examined": examined,
        "archive_references": references,
        "referenced_archive_checks": checks,
        "requested_identity": {"member_path": MEMBER, "sha256": EXPECTED_SHA256},
        "access_or_coverage_errors": errors,
        "coverage_notes": [
            "Search is limited to the listed existing storage roots and task/staging-named top-level directories; it is not a global filesystem search.",
            "Symlinks and virtual/system roots are not traversed. Only supported text formats with manifest-like names or located in task-oriented directories are read.",
            "Archive candidates are checked only when a supported text file explicitly references an archive path; only Python standard-library ZIP and tar formats are checked.",
            "No archive reference, unreadable file, or absent member establishes absence outside the locations and files actually examined."
        ]
    }
    print(json.dumps(result, sort_keys=True))


if __name__ == "__main__":
    main()

