import hashlib
import json
import os
import tarfile
import zipfile

# Identities supplied in the task and its original-input metadata.
references = {
    "llm_inputs/49d4eca1e71d79187f59076c1545879923214ee0db6ffc27dd898fd4fc4493f2.json": "49d4eca1e71d79187f59076c1545879923214ee0db6ffc27dd898fd4fc4493f2",
    "llm_inputs/3d4998877404d211aadf435d7eae62345285f15560f42f216641728c8d42c531.json": "3d4998877404d211aadf435d7eae62345285f15560f42f216641728c8d42c531",
    "llm_inputs/e6ddcbed1083568c14378441603b3ef74e3fe01fed8f81b812ae51631e5da03e.json": "e6ddcbed1083568c14378441603b3ef74e3fe01fed8f81b812ae51631e5da03e",
}
expected = {p: d.lower() for p, d in references.items()}
basenames = {os.path.basename(p): p for p in references}
archive_suffixes = (".zip", ".tar", ".tgz", ".tar.gz", ".tar.bz2", ".tar.xz", ".tbz", ".tbz2", ".txz")
skip_dirs = {"/proc", "/sys", "/dev", "/run", "/root/scripts"}

result = {
    "purpose": "Reconcile supplied artifact identities by path and SHA-256; member contents are not printed or inspected.",
    "references": [{"path": p, "expected_sha256": h} for p, h in references.items()],
    "search_roots": ["/"],
    "excluded_paths": sorted(skip_dirs),
    "coverage": {"filesystem_walk_completed": False, "archive_formats": ["ZIP", "TAR (including compressed TAR)"]},
    "direct_file_hits": [],
    "archive_members": [],
    "errors": [],
    "error_count": 0,
}


def digest_stream(stream):
    h = hashlib.sha256()
    while True:
        block = stream.read(1024 * 1024)
        if not block:
            break
        h.update(block)
    return h.hexdigest()


def note_error(path, operation, exc):
    result["error_count"] += 1
    if len(result["errors"]) < 200:
        result["errors"].append({"path": path, "operation": operation, "error": str(exc)})


def archive_check(path):
    try:
        if zipfile.is_zipfile(path):
            with zipfile.ZipFile(path) as zf:
                for info in zf.infolist():
                    if info.is_dir():
                        continue
                    member = info.filename
                    try:
                        with zf.open(info, "r") as stream:
                            observed = digest_stream(stream)
                    except Exception as exc:
                        note_error(path + "!" + member, "read ZIP member", exc)
                        continue
                    ref_path = basenames.get(os.path.basename(member))
                    if observed in expected.values() or ref_path is not None:
                        result["archive_members"].append({
                            "archive": path,
                            "member_path": member,
                            "sha256": observed,
                            "candidate_reference": ref_path,
                            "exact_path_match": ref_path is not None and member == ref_path,
                            "digest_match": ref_path is not None and observed == expected[ref_path],
                        })
            return
        if tarfile.is_tarfile(path):
            with tarfile.open(path, mode="r:*") as tf:
                for info in tf:
                    if not info.isfile():
                        continue
                    member = info.name
                    stream = None
                    try:
                        stream = tf.extractfile(info)
                        if stream is None:
                            raise OSError("archive member did not yield a readable stream")
                        observed = digest_stream(stream)
                    except Exception as exc:
                        note_error(path + "!" + member, "read TAR member", exc)
                        continue
                    finally:
                        if stream is not None:
                            stream.close()
                    ref_path = basenames.get(os.path.basename(member))
                    if observed in expected.values() or ref_path is not None:
                        result["archive_members"].append({
                            "archive": path,
                            "member_path": member,
                            "sha256": observed,
                            "candidate_reference": ref_path,
                            "exact_path_match": ref_path is not None and member == ref_path,
                            "digest_match": ref_path is not None and observed == expected[ref_path],
                        })
    except Exception as exc:
        note_error(path, "inspect archive", exc)


try:
    for current, dirs, files in os.walk("/", topdown=True, followlinks=False, onerror=lambda e: note_error(getattr(e, "filename", "/"), "walk directory", e)):
        dirs[:] = [d for d in dirs if os.path.join(current, d) not in skip_dirs]
        for name in files:
            path = os.path.join(current, name)
            if path.startswith("/root/scripts/"):
                continue
            ref_path = basenames.get(name)
            if ref_path is not None:
                try:
                    if os.path.isfile(path):
                        with open(path, "rb") as stream:
                            observed = digest_stream(stream)
                        result["direct_file_hits"].append({
                            "path": path,
                            "candidate_reference": ref_path,
                            "sha256": observed,
                            "digest_match": observed == expected[ref_path],
                        })
                except Exception as exc:
                    note_error(path, "hash direct file", exc)
            low = name.lower()
            if low.endswith(archive_suffixes):
                archive_check(path)
    result["coverage"]["filesystem_walk_completed"] = True
except Exception as exc:
    note_error("/", "filesystem walk", exc)

result["assessment"] = {
    "exact_archive_matches": [m for m in result["archive_members"] if m["exact_path_match"] and m["digest_match"]],
    "digest_matches_at_other_paths": [m for m in result["archive_members"] if m["digest_match"] and not m["exact_path_match"]],
    "interpretation": "A candidate is verified against a supplied reference only when its archive member path and digest both match. A basename hit, direct-file hit, or digest-only match is reported separately and does not by itself establish an exact archive-member match."
}
print(json.dumps(result, sort_keys=True))

