import hashlib
import json
import os
import tarfile
import zipfile

REFERENCE = "llm_inputs/312bb20c3e1dc536888ff2bf35274d3fb4beaef7d7dd3f5c671fc9766cb569a7.json"
EXPECTED_SHA256 = "312bb20c3e1dc536888ff2bf35274d3fb4beaef7d7dd3f5c671fc9766cb569a7"
EXCLUDED_DIRS = {"/dev", "/proc", "/run", "/sys", "/root/scripts"}
ARCHIVE_SUFFIXES = (
    ".zip", ".jar", ".whl", ".egg", ".tar", ".tar.gz", ".tgz",
    ".tar.bz2", ".tbz", ".tbz2", ".tar.xz", ".txz", ".tar.zst",
)
CHUNK_SIZE = 1024 * 1024


def likely_archive(path):
    lower = path.lower()
    if lower.endswith(ARCHIVE_SUFFIXES):
        return True
    try:
        with open(path, "rb") as stream:
            head = stream.read(4)
            if head.startswith(b"PK\x03\x04") or head.startswith(b"PK\x05\x06") or head.startswith(b"PK\x07\x08"):
                return True
            stream.seek(257)
            return stream.read(5) == b"ustar"
    except OSError:
        return False


def hash_stream(stream):
    digest = hashlib.sha256()
    while True:
        chunk = stream.read(CHUNK_SIZE)
        if not chunk:
            break
        digest.update(chunk)
    return digest.hexdigest()


def main():
    archives = []
    walk_errors = []
    archive_errors = []
    matches = []
    dirs_seen = 0
    files_seen = 0

    def on_walk_error(error):
        walk_errors.append({"path": getattr(error, "filename", None), "error": str(error)})

    for root, dirs, files in os.walk("/", topdown=True, followlinks=False, onerror=on_walk_error):
        dirs_seen += 1
        dirs[:] = [d for d in dirs if os.path.join(root, d) not in EXCLUDED_DIRS]
        for name in files:
            path = os.path.join(root, name)
            files_seen += 1
            if likely_archive(path):
                archives.append(path)

    for archive_path in archives:
        try:
            if zipfile.is_zipfile(archive_path):
                with zipfile.ZipFile(archive_path, "r") as archive:
                    for info in archive.infolist():
                        if info.filename != REFERENCE or info.is_dir():
                            continue
                        try:
                            with archive.open(info, "r") as member:
                                actual = hash_stream(member)
                            matches.append({
                                "archive_source": archive_path,
                                "member_path": info.filename,
                                "sha256": actual,
                                "digest_matches_reference": actual == EXPECTED_SHA256,
                                "provenance": "Exact member path and digest checked against the task-supplied original-input reference; archive source path recorded.",
                            })
                        except Exception as error:
                            archive_errors.append({"archive": archive_path, "member": info.filename, "error": str(error)})
            elif tarfile.is_tarfile(archive_path):
                with tarfile.open(archive_path, "r:*") as archive:
                    for info in archive.getmembers():
                        if info.name != REFERENCE or not info.isfile():
                            continue
                        try:
                            member = archive.extractfile(info)
                            if member is None:
                                raise OSError("Archive member could not be opened for hashing")
                            with member:
                                actual = hash_stream(member)
                            matches.append({
                                "archive_source": archive_path,
                                "member_path": info.name,
                                "sha256": actual,
                                "digest_matches_reference": actual == EXPECTED_SHA256,
                                "provenance": "Exact member path and digest checked against the task-supplied original-input reference; archive source path recorded.",
                            })
                        except Exception as error:
                            archive_errors.append({"archive": archive_path, "member": info.name, "error": str(error)})
        except Exception as error:
            archive_errors.append({"archive": archive_path, "error": str(error)})

    verified = any(item["digest_matches_reference"] for item in matches)
    report = {
        "purpose": "Verify the exact task-supplied original-input archive member and SHA-256 without printing member contents.",
        "reference": {"member_path": REFERENCE, "sha256": EXPECTED_SHA256},
        "verification_status": "verified" if verified else ("member_found_digest_mismatch" if matches else "not_verified"),
        "verified_member_count": sum(1 for item in matches if item["digest_matches_reference"]),
        "exact_member_matches": matches,
        "coverage": {
            "walk_root": "/",
            "directories_seen": dirs_seen,
            "files_seen": files_seen,
            "archive_candidates_examined": len(archives),
            "excluded_directories": sorted(EXCLUDED_DIRS),
            "walk_errors_count": len(walk_errors),
            "archive_errors_count": len(archive_errors),
        },
        "walk_errors": walk_errors[:50],
        "archive_errors": archive_errors[:50],
        "limitations": "Only accessible files recognized as ZIP or tar archives (by common suffix or ZIP/ustar signature) were checked. No member contents are included in this report. A not_verified result is not proof that the artifact is absent from unexamined or inaccessible sources.",
    }
    print(json.dumps(report, sort_keys=True))


if __name__ == "__main__":
    main()

