import hashlib
import json
import os
import stat
import tarfile
import zipfile

TARGET = "llm_inputs/afdb72cfa5fdb9c5ba8e11995742e863c2ece5b7591355565a4a80ef8d096446.json"
EXPECTED_SHA256 = "afdb72cfa5fdb9c5ba8e11995742e863c2ece5b7591355565a4a80ef8d096446"
SKIP_DIRS = {"/proc", "/sys", "/dev", "/run", "/root/scripts"}
ARCHIVE_SUFFIXES = (
    ".zip", ".tar", ".tgz", ".tar.gz", ".tar.bz2", ".tbz", ".tbz2",
    ".tar.xz", ".txz", ".tar.zst", ".7z", ".rar",
)


def canonical_member(name):
    return name.replace("\\", "/").lstrip("./")


def digest_stream(stream):
    digest = hashlib.sha256()
    while True:
        block = stream.read(1024 * 1024)
        if not block:
            break
        digest.update(block)
    return digest.hexdigest()


def is_archive_candidate(path):
    lower = path.lower()
    if lower.endswith(ARCHIVE_SUFFIXES):
        return True
    try:
        with open(path, "rb") as stream:
            return stream.read(4).startswith(b"PK\x03\x04") or stream.read(0).startswith(b"PK")
    except OSError:
        return False


def inspect_archive(path, errors):
    try:
        if zipfile.is_zipfile(path):
            with zipfile.ZipFile(path, "r") as archive:
                for info in archive.infolist():
                    if not info.is_dir() and canonical_member(info.filename) == TARGET:
                        with archive.open(info, "r") as member:
                            actual = digest_stream(member)
                        return {
                            "archive": path,
                            "member": info.filename,
                            "sha256": actual,
                            "matches_expected": actual == EXPECTED_SHA256,
                            "archive_format": "zip",
                        }
            return None

        if tarfile.is_tarfile(path):
            with tarfile.open(path, mode="r:*") as archive:
                for member in archive:
                    if member.isfile() and canonical_member(member.name) == TARGET:
                        stream = archive.extractfile(member)
                        if stream is None:
                            errors.append({"path": path, "error": "matched TAR member could not be read"})
                            return None
                        with stream:
                            actual = digest_stream(stream)
                        return {
                            "archive": path,
                            "member": member.name,
                            "sha256": actual,
                            "matches_expected": actual == EXPECTED_SHA256,
                            "archive_format": "tar",
                        }
        return None
    except (OSError, EOFError, tarfile.TarError, zipfile.BadZipFile, RuntimeError) as exc:
        errors.append({"path": path, "error": f"{type(exc).__name__}: {exc}"})
        return None


def main():
    files_seen = 0
    candidates_seen = 0
    archives_checked = 0
    traversal_errors = []
    archive_errors = []
    matches = []

    for root, dirs, files in os.walk("/", topdown=True, followlinks=False):
        kept = []
        for dirname in dirs:
            candidate = os.path.join(root, dirname)
            if candidate in SKIP_DIRS:
                continue
            kept.append(dirname)
        dirs[:] = kept

        for name in files:
            path = os.path.join(root, name)
            files_seen += 1
            try:
                mode = os.stat(path, follow_symlinks=False).st_mode
            except OSError as exc:
                if len(traversal_errors) < 100:
                    traversal_errors.append({"path": path, "error": f"{type(exc).__name__}: {exc}"})
                continue
            if not stat.S_ISREG(mode) or not is_archive_candidate(path):
                continue
            candidates_seen += 1
            archives_checked += 1
            result = inspect_archive(path, archive_errors)
            if result is not None:
                matches.append(result)

    if any(item["matches_expected"] for item in matches):
        result_status = "verified"
    elif matches:
        result_status = "member_found_digest_mismatch"
    else:
        result_status = "not_verified"

    report = {
        "purpose": "Verify the identity of the task-supplied artifact by exact archive member path and SHA-256; artifact contents were not inspected.",
        "task_supplied_reference": {
            "archive_member": TARGET,
            "expected_sha256": EXPECTED_SHA256,
            "provenance_note": "The path and digest are task-supplied identifiers; this run verifies archive location and bytes, not independent provenance of the archive itself.",
        },
        "status": result_status,
        "matches": matches,
        "coverage": {
            "filesystem_root_walked": "/",
            "excluded_directories": sorted(SKIP_DIRS),
            "regular_files_seen": files_seen,
            "archive_candidates_recognized": candidates_seen,
            "archives_checked": archives_checked,
            "archive_errors_count": len(archive_errors),
            "archive_errors_sample": archive_errors[:50],
            "traversal_errors_count_recorded": len(traversal_errors),
            "traversal_errors_sample": traversal_errors[:50],
            "limitations": "Only accessible files recognized as ZIP or TAR candidates were checked. Excluded or inaccessible paths, unrecognized archive formats, and other sources were not verified; no-match does not establish absence outside examined archives.",
        },
    }
    print(json.dumps(report, sort_keys=True))


if __name__ == "__main__":
    main()

