import hashlib
import json
import os
import tarfile
import zipfile

MEMBER = "llm_inputs/5cbb646a397eb99a0cdbef8ea16efafa71e9959dddd540141a1f032eeed34a77.json"
EXPECTED = "5cbb646a397eb99a0cdbef8ea16efafa71e9959dddd540141a1f032eeed34a77"
EXCLUDED = {"/proc", "/sys", "/dev", "/run", "/root/scripts"}

report = {
    "purpose": "Locate and inspect only the exact task-specified artifact; verify SHA-256 before interpreting contents.",
    "task_supplied_reference": {
        "path_or_archive_member": MEMBER,
        "expected_sha256": EXPECTED,
        "provenance_basis": "Path and digest are supplied by task metadata; archive provenance is not independently established by this search."
    },
    "search": {
        "filesystem_root": "/",
        "excluded_locations": sorted(EXCLUDED),
        "regular_files_seen": 0,
        "recognized_zip_archives": 0,
        "recognized_tar_archives": 0,
        "access_or_parse_errors_count": 0,
        "access_or_parse_errors_sample": [],
        "limitations": "Examines accessible filesystem paths and recognized ZIP/TAR files while excluding the listed locations. It does not establish absence in inaccessible or excluded paths, unrecognized archive formats, nested archives that are not independently reachable, or other sources."
    },
    "candidates": []
}


def record_error(path, exc):
    search = report["search"]
    search["access_or_parse_errors_count"] += 1
    if len(search["access_or_parse_errors_sample"]) < 50:
        search["access_or_parse_errors_sample"].append({"path": path, "error": type(exc).__name__ + ": " + str(exc)})


def inspect_bytes(source, data):
    digest = hashlib.sha256(data).hexdigest()
    item = {
        "source": source,
        "provenance_basis": "Located at this filesystem path or archive member; task-supplied path/digest are the comparison reference.",
        "access_result": "readable",
        "byte_length": len(data),
        "actual_sha256": digest,
        "digest_matches_expected": digest == EXPECTED,
        "contents": None,
        "parser_status": "not_parsed_digest_mismatch"
    }
    if digest == EXPECTED:
        try:
            text = data.decode("utf-8")
            item["contents"] = text
            try:
                item["parsed_json"] = json.loads(text)
                item["parser_status"] = "parsed_json"
            except json.JSONDecodeError as exc:
                item["parser_status"] = "json_parse_error"
                item["parser_error"] = str(exc)
        except UnicodeDecodeError as exc:
            item["parser_status"] = "utf8_decode_error"
            item["parser_error"] = str(exc)
    report["candidates"].append(item)


def is_under_excluded(path):
    path = os.path.abspath(path)
    return any(path == excluded or path.startswith(excluded + os.sep) for excluded in EXCLUDED)


def walk_error(exc):
    record_error(getattr(exc, "filename", None) or "<walk>", exc)

for root, dirs, files in os.walk("/", topdown=True, onerror=walk_error, followlinks=False):
    dirs[:] = [d for d in dirs if not is_under_excluded(os.path.join(root, d))]
    if is_under_excluded(root):
        dirs[:] = []
        continue
    for name in files:
        path = os.path.join(root, name)
        if is_under_excluded(path):
            continue
        report["search"]["regular_files_seen"] += 1
        try:
            rel_parts = os.path.normpath(path).split(os.sep)
            member_parts = MEMBER.split("/")
            if len(rel_parts) >= len(member_parts) and rel_parts[-len(member_parts):] == member_parts:
                with open(path, "rb") as f:
                    inspect_bytes({"kind": "filesystem_file", "path": path, "exact_relative_suffix": MEMBER}, f.read())
        except OSError as exc:
            record_error(path, exc)

        try:
            if zipfile.is_zipfile(path):
                report["search"]["recognized_zip_archives"] += 1
                try:
                    with zipfile.ZipFile(path, "r") as zf:
                        for info in zf.infolist():
                            if info.filename == MEMBER and not info.is_dir():
                                inspect_bytes({"kind": "zip_member", "archive": path, "member": info.filename}, zf.read(info))
                except (OSError, zipfile.BadZipFile, RuntimeError, EOFError) as exc:
                    record_error(path, exc)
            else:
                try:
                    with tarfile.open(path, mode="r:*") as tf:
                        report["search"]["recognized_tar_archives"] += 1
                        for info in tf.getmembers():
                            if info.name == MEMBER and info.isfile():
                                stream = tf.extractfile(info)
                                if stream is None:
                                    record_error(path + "::" + info.name, "member could not be read")
                                else:
                                    with stream:
                                        inspect_bytes({"kind": "tar_member", "archive": path, "member": info.name}, stream.read())
                except (tarfile.TarError, OSError, EOFError) as exc:
                    # A non-archive file is an expected probe result, not an access failure.
                    pass
        except OSError as exc:
            record_error(path, exc)

report["status"] = "verified_and_inspected" if any(c["digest_matches_expected"] and c["parser_status"] == "parsed_json" for c in report["candidates"]) else ("candidate_digest_matched_but_inspection_inconclusive" if any(c["digest_matches_expected"] for c in report["candidates"]) else "not_verified_in_examined_locations")
report["finding"] = "Only digest-matching content is interpreted. No matching bytes means the exact artifact was not verified in the examined accessible paths and recognized archives; it does not prove absence elsewhere."
print(json.dumps(report, ensure_ascii=False, sort_keys=True))

