#!/usr/bin/env python3
import hashlib
import json
import os
import tarfile
import zipfile
from pathlib import Path

RELATIVE = "llm_inputs/579ef50af098d92369eb3f5a678a13dd001f3ee0ef6cfbebd09a96566486ecec.json"
EXPECTED = "579ef50af098d92369eb3f5a678a13dd001f3ee0ef6cfbebd09a96566486ecec"
BASENAME = RELATIVE.rsplit("/", 1)[-1]
EXCLUDED = {"/dev", "/proc", "/run", "/sys", "/root/scripts"}

report = {
    "task_supplied_reference": {
        "path_or_archive_member": RELATIVE,
        "expected_sha256": EXPECTED,
        "provenance_basis": "Path, digest, and available_in_archive assertion are task-supplied metadata; archive provenance is not independently established unless observed from a located source."
    },
    "status": "not_verified_in_examined_locations",
    "candidates": [],
    "standalone_files_examined_with_matching_basename": 0,
    "archives_examined": {"zip": 0, "tar": 0},
    "traversal_errors": [],
    "archive_errors": [],
    "excluded_locations": sorted(EXCLUDED),
    "coverage": "Walks / without following directory symlinks; hashes standalone files whose basename matches the supplied filename and checks recognized ZIP/TAR archives for the exact member path. Excludes the listed locations. Does not inspect nested archives, follow symlinks, or establish absence from inaccessible or excluded locations."
}


def digest_bytes(data):
    return hashlib.sha256(data).hexdigest()


def inspect_candidate(source, data, source_kind):
    actual = digest_bytes(data)
    item = {"source": source, "source_kind": source_kind, "sha256": actual}
    if actual != EXPECTED:
        item["identity"] = "digest_mismatch"
        report["candidates"].append(item)
        return
    item["identity"] = "digest_verified"
    try:
        text = data.decode("utf-8")
        item["encoding"] = "utf-8"
        try:
            item["parsed_content"] = json.loads(text)
            item["parser_status"] = "json_parsed"
        except json.JSONDecodeError as exc:
            item["parser_status"] = "json_parse_error"
            item["parser_error"] = {"message": exc.msg, "line": exc.lineno, "column": exc.colno}
    except UnicodeDecodeError as exc:
        item["parser_status"] = "utf8_decode_error"
        item["parser_error"] = str(exc)
    report["candidates"].append(item)


def record_error(collection, path, exc):
    if len(report[collection]) < 100:
        report[collection].append({"path": str(path), "error": f"{type(exc).__name__}: {exc}"})


for root, dirs, files in os.walk("/", topdown=True, followlinks=False, onerror=lambda e: record_error("traversal_errors", getattr(e, "filename", "/"), e)):
    root_path = os.path.abspath(root)
    dirs[:] = [d for d in dirs if os.path.join(root_path, d) not in EXCLUDED and not os.path.islink(os.path.join(root_path, d))]
    for name in files:
        path = os.path.join(root_path, name)
        if os.path.islink(path):
            continue
        if name == BASENAME:
            report["standalone_files_examined_with_matching_basename"] += 1
            try:
                with open(path, "rb") as f:
                    inspect_candidate(path, f.read(), "standalone_file")
            except OSError as exc:
                record_error("traversal_errors", path, exc)
        try:
            if zipfile.is_zipfile(path):
                report["archives_examined"]["zip"] += 1
                try:
                    with zipfile.ZipFile(path, "r") as archive:
                        for member in archive.infolist():
                            if member.filename == RELATIVE and not member.is_dir():
                                with archive.open(member, "r") as stream:
                                    inspect_candidate(f"{path}!/{member.filename}", stream.read(), "zip_member")
                except (OSError, zipfile.BadZipFile, RuntimeError, EOFError) as exc:
                    record_error("archive_errors", path, exc)
            elif tarfile.is_tarfile(path):
                report["archives_examined"]["tar"] += 1
                try:
                    with tarfile.open(path, mode="r:*") as archive:
                        for member in archive:
                            if member.name == RELATIVE and member.isfile():
                                stream = archive.extractfile(member)
                                if stream is None:
                                    record_error("archive_errors", path, RuntimeError("matching member could not be read"))
                                else:
                                    with stream:
                                        inspect_candidate(f"{path}!/{member.name}", stream.read(), "tar_member")
                except (OSError, tarfile.TarError, EOFError) as exc:
                    record_error("archive_errors", path, exc)
        except (OSError, zipfile.BadZipFile, tarfile.TarError, EOFError) as exc:
            record_error("archive_errors", path, exc)

verified = [c for c in report["candidates"] if c["identity"] == "digest_verified"]
if verified:
    report["status"] = "digest_verified"
report["matching_digest_candidate_count"] = len(verified)
report["provenance_observation"] = (
    "The source path and container type are observed for each matching digest; the task-supplied metadata is the basis for the expected path and digest. No stronger chain of custody is inferred."
    if verified else
    "No digest-matching source was observed in the examined locations; the task-supplied available_in_archive assertion was not independently confirmed."
)
print(json.dumps(report, ensure_ascii=False, sort_keys=True))

