import json
import socket
import sys
import time

TARGET = "192.168.1.3"
PORT = 161
TIMEOUT_SECONDS = 3.0


def ber_length(length):
    if length < 0x80:
        return bytes([length])
    raw = length.to_bytes((length.bit_length() + 7) // 8, "big")
    return bytes([0x80 | len(raw)]) + raw


def tlv(tag, value):
    return bytes([tag]) + ber_length(len(value)) + value


def ber_integer(value):
    if value == 0:
        raw = b"\x00"
    else:
        size = max(1, (value.bit_length() + 7) // 8)
        raw = value.to_bytes(size, "big", signed=False)
        if raw[0] & 0x80:
            raw = b"\x00" + raw
    return tlv(0x02, raw)


def ber_oid(numbers):
    if len(numbers) < 2 or numbers[0] > 2 or (numbers[0] < 2 and numbers[1] > 39):
        raise ValueError("invalid OID")
    encoded = bytearray()
    for number in [40 * numbers[0] + numbers[1]] + numbers[2:]:
        if number < 0:
            raise ValueError("negative OID arc")
        parts = [number & 0x7f]
        number >>= 7
        while number:
            parts.append(0x80 | (number & 0x7f))
            number >>= 7
        encoded.extend(reversed(parts))
    return tlv(0x06, bytes(encoded))


def build_discovery_request():
    request_id = int(time.time() * 1000) & 0x7fffffff
    varbind = tlv(0x30, ber_oid([1, 3, 6, 1, 2, 1, 1, 1, 0]) + tlv(0x05, b""))
    varbind_list = tlv(0x30, varbind)
    get_request = tlv(0xA0, ber_integer(request_id) + ber_integer(0) + ber_integer(0) + varbind_list)
    scoped_pdu = tlv(0x30, tlv(0x04, b"") + tlv(0x04, b"") + get_request)

    # USM discovery uses empty authoritative engine ID and user name, with
    # zeroed boots/time and empty authentication/privacy parameters.
    usm_parameters = tlv(0x30,
                         tlv(0x04, b"") + ber_integer(0) + ber_integer(0) +
                         tlv(0x04, b"") + tlv(0x04, b"") + tlv(0x04, b""))
    global_data = tlv(0x30,
                      ber_integer(request_id) + ber_integer(65507) +
                      tlv(0x04, b"\x04") + ber_integer(3))
    message = tlv(0x30,
                  ber_integer(3) + global_data + tlv(0x04, usm_parameters) +
                  tlv(0x04, scoped_pdu))
    return request_id, message


def read_tlv(data, offset=0):
    if offset + 2 > len(data):
        raise ValueError("truncated BER tag/length")
    tag = data[offset]
    first = data[offset + 1]
    pos = offset + 2
    if first < 0x80:
        length = first
    else:
        count = first & 0x7f
        if count == 0:
            raise ValueError("indefinite BER length is not valid in SNMP")
        if count > 4 or pos + count > len(data):
            raise ValueError("invalid or truncated BER length")
        length = int.from_bytes(data[pos:pos + count], "big")
        pos += count
    end = pos + length
    if end > len(data):
        raise ValueError("truncated BER value")
    return tag, data[pos:end], end


def children(data):
    items = []
    pos = 0
    while pos < len(data):
        tag, value, end = read_tlv(data, pos)
        items.append((tag, value))
        pos = end
    return items


def integer_value(item):
    tag, value = item
    if tag != 0x02 or not value:
        raise ValueError("expected BER INTEGER")
    return int.from_bytes(value, "big", signed=True)


def decode_oid(value):
    if not value:
        raise ValueError("empty BER OID")
    subids = []
    current = 0
    continuing = False
    for byte in value:
        current = (current << 7) | (byte & 0x7f)
        continuing = bool(byte & 0x80)
        if not continuing:
            subids.append(current)
            current = 0
    if continuing:
        raise ValueError("truncated BER OID arc")
    first = subids.pop(0)
    if first < 40:
        arcs = [0, first]
    elif first < 80:
        arcs = [1, first - 40]
    else:
        arcs = [2, first - 80]
    return ".".join(str(x) for x in arcs + subids)


def parse_response(data):
    tag, body, end = read_tlv(data)
    if tag != 0x30 or end != len(data):
        raise ValueError("response is not one complete BER SEQUENCE")
    fields = children(body)
    if len(fields) != 4:
        raise ValueError("SNMP message must contain four top-level fields")
    version = integer_value(fields[0])
    if version != 3:
        raise ValueError("response is not SNMPv3 (version is %d)" % version)
    if fields[1][0] != 0x30:
        raise ValueError("SNMPv3 globalData is not a SEQUENCE")
    global_fields = children(fields[1][1])
    if len(global_fields) != 4:
        raise ValueError("invalid SNMPv3 globalData field count")
    msg_id = integer_value(global_fields[0])
    max_size = integer_value(global_fields[1])
    if global_fields[2][0] != 0x04 or global_fields[3][0] != 0x02:
        raise ValueError("invalid SNMPv3 globalData types")
    security_model = integer_value(global_fields[3])

    security_summary = {"security_parameters_parse": "unavailable"}
    if fields[2][0] == 0x04:
        try:
            usm_tag, usm_body, usm_end = read_tlv(fields[2][1])
            if usm_tag != 0x30 or usm_end != len(fields[2][1]):
                raise ValueError("USM parameters are not one SEQUENCE")
            usm = children(usm_body)
            if len(usm) != 6 or any(tag != 0x04 for tag, _ in usm[:1] + usm[3:]):
                raise ValueError("invalid USM parameter fields")
            security_summary = {
                "security_parameters_parse": "parsed",
                "authoritative_engine_id_hex": usm[0][1].hex(),
                "authoritative_engine_boots": integer_value(usm[1]),
                "authoritative_engine_time": integer_value(usm[2]),
                "user_name_length": len(usm[3][1]),
                "authentication_parameters_length": len(usm[4][1]),
                "privacy_parameters_length": len(usm[5][1]),
            }
        except (ValueError, IndexError) as exc:
            security_summary = {"security_parameters_parse": "malformed", "detail": str(exc)}

    result = {
        "version": version,
        "msg_id": msg_id,
        "msg_max_size": max_size,
        "msg_flags_hex": global_fields[2][1].hex(),
        "security_model": security_model,
        **security_summary,
        "scoped_pdu_parse": "unavailable",
    }
    if fields[3][0] != 0x04:
        result["scoped_pdu_parse"] = "unexpected_field_type"
        return result
    try:
        scoped_tag, scoped_body, scoped_end = read_tlv(fields[3][1])
        if scoped_tag != 0x30 or scoped_end != len(fields[3][1]):
            raise ValueError("scoped PDU is not one complete SEQUENCE")
        scoped = children(scoped_body)
        if len(scoped) != 3 or scoped[0][0] != 0x04 or scoped[1][0] != 0x04:
            raise ValueError("invalid scoped PDU fields")
        pdu_tag, pdu_body = scoped[2]
        if pdu_tag not in (0xA0, 0xA1, 0xA2, 0xA3, 0xA4, 0xA5, 0xA6, 0xA7, 0xA8, 0xA9):
            raise ValueError("unexpected scoped PDU tag 0x%02x" % pdu_tag)
        pdu = children(pdu_body)
        if len(pdu) != 4:
            raise ValueError("invalid PDU field count")
        result.update({
            "scoped_pdu_parse": "parsed",
            "context_engine_id_hex": scoped[0][1].hex(),
            "context_name_length": len(scoped[1][1]),
            "pdu_type": {0xA0: "get_request", 0xA1: "get_next_request", 0xA2: "response",
                         0xA3: "set_request", 0xA4: "trap_v1", 0xA5: "get_bulk_request",
                         0xA6: "inform_request", 0xA7: "trap_v2", 0xA8: "report",
                         0xA9: "get_subtree"}.get(pdu_tag, "unknown"),
            "request_id": integer_value(pdu[0]),
            "error_status": integer_value(pdu[1]),
            "error_index": integer_value(pdu[2]),
        })
        if pdu[3][0] != 0x30:
            raise ValueError("varbind list is not a SEQUENCE")
        varbinds = []
        for varbind_tag, varbind_body in children(pdu[3][1]):
            if varbind_tag != 0x30:
                raise ValueError("varbind is not a SEQUENCE")
            pair = children(varbind_body)
            if len(pair) != 2 or pair[0][0] != 0x06:
                raise ValueError("malformed varbind")
            varbinds.append({"oid": decode_oid(pair[0][1]), "value_tag": "0x%02x" % pair[1][0],
                             "value_hex": pair[1][1].hex()})
        result["varbinds"] = varbinds
    except (ValueError, IndexError) as exc:
        result["scoped_pdu_parse"] = "malformed"
        result["scoped_pdu_error"] = str(exc)
    return result


def main():
    request_id, request = build_discovery_request()
    output = {
        "target": TARGET,
        "port": PORT,
        "protocol": "SNMPv3 unauthenticated engine discovery over UDP",
        "credentials_attempted": False,
        "timeout_seconds": TIMEOUT_SECONDS,
        "request_id": request_id,
        "request_bytes_sent": len(request),
        "request_hex": request.hex(),
    }
    sock = None
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        sock.settimeout(TIMEOUT_SECONDS)
        started = time.monotonic()
        sock.sendto(request, (TARGET, PORT))
        output["outcome"] = "request_sent_waiting_for_response"
        data, peer = sock.recvfrom(65535)
        output["elapsed_seconds"] = round(time.monotonic() - started, 6)
        output["response_peer"] = "%s:%d" % (peer[0], peer[1])
        output["response_bytes"] = len(data)
        output["response_hex"] = data.hex()
        try:
            parsed = parse_response(data)
            output["protocol_response"] = True
            output["parsed_response"] = parsed
            output["outcome"] = "snmpv3_response_parsed" if parsed.get("scoped_pdu_parse") == "parsed" else "snmpv3_response_malformed"
        except (ValueError, IndexError) as exc:
            output["protocol_response"] = False
            output["outcome"] = "unexpected_or_malformed_response"
            output["parse_error"] = str(exc)
    except socket.timeout:
        output["outcome"] = "timeout_no_response"
        output["detail"] = "No UDP datagram arrived before the configured timeout; this does not establish service absence."
    except OSError as exc:
        output["outcome"] = "transport_error"
        output["error_type"] = type(exc).__name__
        output["error"] = str(exc)
        output["errno"] = exc.errno
        output["detail"] = "A transport-level socket error occurred; it is distinct from a parsed SNMP response or timeout."
    except Exception as exc:
        output["outcome"] = "execution_failure"
        output["error_type"] = type(exc).__name__
        output["error"] = str(exc)
    finally:
        if sock is not None:
            sock.close()
    print(json.dumps(output, sort_keys=True))
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception as exc:
        print(json.dumps({"outcome": "execution_failure", "error_type": type(exc).__name__, "error": str(exc),
                          "target": TARGET, "port": PORT, "credentials_attempted": False}, sort_keys=True))
        sys.exit(1)
